    # ---------------------------------------------------------------- runtime
    def _ev(self, name):
        def call(*_a):
            fn = getattr(self, name, None)
            if fn is not None:
                fn()
        return call

    def _res(self, path):
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), path)

    def closeEvent(self, event):
        e = EventArgs()
        fn = getattr(self, "Form1_FormClosing", None)
        if fn is not None:
            fn(e)
        if e.Cancel:
            event.ignore()
            return
        event.accept()
        fn = getattr(self, "Form1_FormClosed", None)
        if fn is not None:
            fn()

    # ---------------------------------------------------------------- data sources
    def FillAll(self):
        """Fill every data source of the form from its database (like TableAdapter.Fill)."""
        return self._dbbind.FillAll(self._db_sources)

    def UpdateAll(self):
        """Save the changes of every data source to the database (TableAdapterManager.UpdateAll)."""
        return self._dbbind.UpdateAll(self._db_sources)
